// GENERATED by scripts/sync-shared.mjs from src/lib. Do not edit by hand.
// Pure ingestion logic: payload + current content -> what should change.
// The edge function, the local importer and the tests all call this, so the
// behaviour you test is the behaviour that runs in production.
import type { Item, Series } from "./types.ts";
import {
  type IngestPayload,
  type IngestItem,
  type IngestResult,
  type IngestSeries,
  type ValidationContext,
  payloadSchema,
  readingMinutes,
  validateItem,
} from "./ingest-schema.ts";

export interface ContentSnapshot {
  items: Item[];
  series: Series[];
}

export interface IngestOutcome {
  result: IngestResult;
  /** Full replacement rows to upsert */
  upsertItems: Item[];
  upsertSeries: Series[];
}

export function contentHash(x: unknown): string {
  // Order-stable JSON hash (FNV-1a). Plenty for "did anything change?".
  const s = JSON.stringify(x, (_k, v) =>
    v && typeof v === "object" && !Array.isArray(v)
      ? Object.fromEntries(Object.entries(v).sort(([a], [b]) => a.localeCompare(b)))
      : v,
  );
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16);
}

function toItem(i: IngestItem, prev: Item | undefined, nowIso: string): Item {
  return {
    id: i.id,
    format: i.format,
    headline: i.headline,
    dek: i.dek,
    body: i.body,
    readingMinutes: i.readingMinutes ?? readingMinutes(i.body),
    topics: i.topics,
    // Keep the original publication date on updates: history is not rewritten.
    publishedAt: prev?.publishedAt ?? i.publishedAt ?? nowIso,
    eventDate: i.eventDate,
    timeliness: i.timeliness,
    significance: i.significance,
    status: prev?.corrections?.length ? "corrected" : "published",
    reason: i.reason,
    sources: i.sources,
    caveats: i.caveats,
    seriesId: i.seriesId,
    chapter: i.chapter,
    recap: i.recap,
    person: i.person,
    version: prev ? prev.version + 1 : 1,
    corrections: prev?.corrections,
    discoveredVia: i.discoveredVia,
    sample: i.sample,
  };
}

function toSeries(s: IngestSeries, prev: Series | undefined): Series {
  return {
    id: s.id,
    title: s.title,
    description: s.description,
    subject: s.subject,
    topics: s.topics,
    motif: s.motif,
    status: prev?.status ?? "suggested",
    researchStatus: s.researchStatus,
    totalChapters: s.totalChapters,
    outline: s.outline,
    sources: s.sources,
    reason: s.reason,
    sample: s.sample,
    version: prev ? prev.version + 1 : 1,
  };
}

/** Comparable view of an item, ignoring bookkeeping fields. */
function comparable(i: Item) {
  const { version: _v, status: _s, corrections: _c, publishedAt: _p, ...rest } = i;
  // The database stores "no caveats" as [] and reads back "no value" as undefined; treat them as equal.
  return { ...rest, caveats: rest.caveats ?? [], sample: rest.sample ?? false };
}
function comparableSeries(s: Series) {
  const { version: _v, status: _s, ...rest } = s;
  return { ...rest, sample: rest.sample ?? false };
}

export function ingest(
  raw: unknown,
  current: ContentSnapshot,
  opts: { excludedTopics?: string[]; now?: Date } = {},
): { ok: true; outcome: IngestOutcome } | { ok: false; errors: string[] } {
  const parsed = payloadSchema.safeParse(raw);
  if (!parsed.success) {
    return {
      ok: false,
      errors: parsed.error.issues.map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`),
    };
  }
  const payload: IngestPayload = parsed.data;
  const nowIso = (opts.now ?? new Date()).toISOString();

  const result: IngestResult = {
    accepted: [], rejected: [], seriesAccepted: [], corrected: [], archived: [], warnings: [],
  };
  const upsertItems: Item[] = [];
  const upsertSeries: Series[] = [];

  const seriesById = new Map(current.series.map((s) => [s.id, s]));
  const itemsById = new Map(current.items.map((i) => [i.id, i]));

  // Series first so chapters in the same payload can reference them.
  for (const s of payload.series) {
    const prev = seriesById.get(s.id);
    const next = toSeries(s, prev);
    if (prev && contentHash(comparableSeries(prev)) === contentHash(comparableSeries(next))) {
      result.seriesAccepted.push({ id: s.id, action: "unchanged" });
      continue;
    }
    if (s.outline.length !== s.totalChapters)
      result.warnings.push(`series ${s.id}: outline has ${s.outline.length} entries but totalChapters is ${s.totalChapters}`);
    seriesById.set(s.id, next);
    upsertSeries.push(next);
    result.seriesAccepted.push({ id: s.id, action: prev ? "updated" : "created" });
  }

  const ctx: ValidationContext = {
    existing: [...itemsById.values()]
      .filter((i) => i.status !== "archived")
      .map((i) => ({
        id: i.id,
        headline: i.headline,
        sourceUrls: i.sources.map((s) => s.url),
        seriesId: i.seriesId,
        chapter: i.chapter,
      })),
    knownSeries: Object.fromEntries(
      [...seriesById.values()].map((s) => [s.id, { totalChapters: s.totalChapters, researchStatus: s.researchStatus }]),
    ),
    excludedTopics: opts.excludedTopics ?? [],
  };

  const seenInPayload = new Set<string>();
  for (const i of payload.items) {
    if (seenInPayload.has(i.id)) {
      result.rejected.push({ id: i.id, reasons: ["id appears twice in this payload"] });
      continue;
    }
    seenInPayload.add(i.id);

    const reasons = validateItem(i, ctx);
    if (reasons.length) {
      result.rejected.push({ id: i.id, reasons });
      continue;
    }
    const prev = itemsById.get(i.id);
    const next = toItem(i, prev, nowIso);
    if (prev && contentHash(comparable(prev)) === contentHash(comparable(next))) {
      result.accepted.push({ id: i.id, action: "unchanged" });
      continue;
    }
    upsertItems.push(next);
    itemsById.set(i.id, next);
    // Later items in the same payload must dedupe against this one.
    ctx.existing.push({
      id: next.id, headline: next.headline, sourceUrls: next.sources.map((s) => s.url),
      seriesId: next.seriesId, chapter: next.chapter,
    });
    result.accepted.push({ id: i.id, action: prev ? "updated" : "created" });
  }

  for (const c of payload.corrections) {
    const prev = itemsById.get(c.itemId);
    if (!prev) {
      result.warnings.push(`correction for unknown item ${c.itemId}`);
      continue;
    }
    const next: Item = {
      ...prev,
      status: "corrected",
      version: prev.version + 1,
      corrections: [...(prev.corrections ?? []), { at: nowIso, note: c.note }],
    };
    itemsById.set(prev.id, next);
    const at = upsertItems.findIndex((u) => u.id === prev.id);
    if (at >= 0) upsertItems[at] = next;
    else upsertItems.push(next);
    result.corrected.push(prev.id);
  }

  for (const id of payload.archive) {
    const prev = itemsById.get(id);
    if (!prev) {
      result.warnings.push(`archive: unknown item ${id}`);
      continue;
    }
    const next: Item = { ...prev, status: "archived", version: prev.version + 1 };
    itemsById.set(id, next);
    const at = upsertItems.findIndex((u) => u.id === id);
    if (at >= 0) upsertItems[at] = next;
    else upsertItems.push(next);
    result.archived.push(id);
  }

  return { ok: true, outcome: { result, upsertItems, upsertSeries } };
}
